import urllib.request
for url in ['https://api.github.com/repos/basecamp/fizzy','https://raw.githubusercontent.com/basecamp/fizzy/main/app/helpers/time_helper.rb']:
    try:
        with urllib.request.urlopen(url, timeout=10) as r:
            print('URL', url, 'status', r.status)
            print(r.read(10000).decode('utf-8', 'replace'))
    except Exception as e:
        print('ERROR', url, repr(e))
