cd /app && cat > app/helpers/time_helper.rb <<'RUBY'
module TimeHelper
  def local_time(time, format: :time_or_relative_date, **options)
    options[:class] = token_list(options[:class], "local-time-value")
    options[:data] = (options[:data] || {}).merge(
      local_time_target: "time",
      local_time_format: format.to_s.dasherize
    )

    tag.time datetime: time.utc.iso8601, **options
  end
end
