const DATE_FORMATTER = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric"
})

const DATE_TIME_FORMATTER = new Intl.DateTimeFormat("en-US", {
  year: "2-digit",
  month: "numeric",
  day: "numeric",
  hour: "numeric",
  minute: "2-digit"
})

const LONG_DATE_FORMATTER = new Intl.DateTimeFormat("en-US", {
  year: "numeric",
  month: "short",
  day: "2-digit"
})

const TIME_FORMATTER = new Intl.DateTimeFormat("en-US", {
  hour: "numeric",
  minute: "2-digit"
})

const WEEKDAY_DATE_FORMATTER = new Intl.DateTimeFormat("en-US", {
  weekday: "long",
  month: "long",
  day: "numeric"
})

const RELATIVE_DATE_FORMATTER = new Intl.RelativeTimeFormat("en-US", {
  numeric: "auto"
})

export function formatDate(date) {
  return DATE_FORMATTER.format(date)
}

export function formatDateTime(date) {
  return DATE_TIME_FORMATTER.format(date)
}

export function formatLongDate(date) {
  return LONG_DATE_FORMATTER.format(date)
}

export function formatTime(date) {
  return TIME_FORMATTER.format(date)
}

export function formatWeekdayDate(date) {
  return WEEKDAY_DATE_FORMATTER.format(date)
}

export function formatTimeOrRelativeDate(date, relativeTo = new Date()) {
  const differenceInDays = signedDifferenceInDays(relativeTo, date)

  if (differenceInDays === 0) {
    return formatTime(date)
  } else if (Math.abs(differenceInDays) < 7) {
    return RELATIVE_DATE_FORMATTER.format(differenceInDays, "day")
  } else {
    return formatDate(date)
  }
}

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}
